using System;using System.Collections.Generic;using System.Linq;using HabitatShift.Core;using UnityEditor;using UnityEngine;
namespace HabitatShift.LevelLabR10 { public static class R10Canvas { static readonly Color Board=new Color(.12f,.23f,.16f),Outside=new Color(.055f,.06f,.06f),Grid=new Color(.38f,.55f,.42f,.38f),Stone=new Color(.38f,.39f,.37f); public static void Draw(R10EditorState state,R10Selection selected,R10Tool tool,bool grid,bool targets,bool choke,ref string dragId,ref string dragKind){var l=state.project.level;EditorGUILayout.BeginHorizontal(EditorStyles.helpBox);EditorGUILayout.LabelField("AUTHORING ? Board origin: top-left (0,0)",EditorStyles.miniLabel);GUILayout.FlexibleSpace();if(GUILayout.Button("FOCUS ORIGIN",EditorStyles.miniButton,GUILayout.Width(100)))GUI.FocusControl(null);EditorGUILayout.EndHorizontal();var outer=GUILayoutUtility.GetRect(500,500,GUILayout.ExpandWidth(true),GUILayout.ExpandHeight(true));var cell=Mathf.Min((outer.width-36)/l.cols,(outer.height-36)/l.rows);var rect=new Rect(outer.x+(outer.width-cell*l.cols)*.5f,outer.y+(outer.height-cell*l.rows)*.5f,cell*l.cols,cell*l.rows);Rect Cell(int x,int y)=>R10CanvasCoordinates.BoardToCanvasRect(rect,cell,x,y);var playable=R10Topology.Cells(l);for(int y=0;y<l.rows;y++)for(int x=0;x<l.cols;x++){var r=Cell(x,y);var valid=playable.Contains(new Vector2Int(x,y));EditorGUI.DrawRect(r,valid?Board:Outside);if(valid){EditorGUI.DrawRect(new Rect(r.x+1,r.y+1,r.width-2,1),Grid);EditorGUI.DrawRect(new Rect(r.x+1,r.y+1,1,r.height-2),Grid);}if(grid)GUI.Label(new Rect(r.x+4,r.y+3,r.width-5,14),x+","+y,EditorStyles.miniLabel);}foreach(var o in l.obstacles??Array.Empty<IntPair>()){var r=Cell(o.x,o.y);EditorGUI.DrawRect(new Rect(r.x+4,r.y+4,r.width-8,r.height-8),Stone);GUI.Label(r,"?",Centered(16,Color.white));}foreach(var e in l.elevators??Array.Empty<ElevatorDto>())DrawElevator(Cell(Mathf.FloorToInt(e.entry.x),Mathf.FloorToInt(e.entry.y)),e,selected.id==e.id);foreach(var h in l.habitats??Array.Empty<HabitatDto>())DrawHabitat(l,Cell,h,selected.id==h.id);if(targets)foreach(var t in l.targets??Array.Empty<TargetDto>())DrawSprout(Cell(Mathf.FloorToInt(t.position.x),Mathf.FloorToInt(t.position.y)),t,selected.id==t.id);HandleInput(state,selected,tool,rect,cell,ref dragId,ref dragKind);}
 static void DrawHabitat(LevelDto level,Func<int,int,Rect> cell,HabitatDto h,bool selected){var shape=h.shape??Array.Empty<IntPair>();var active=h.stages!=null&&h.stages.Length>0?h.stages[0].color:h.color;var c=R10AuthoringPalette.ColorFor(active);foreach(var q in shape){var r=cell(h.anchor.x+q.x,h.anchor.y+q.y);EditorGUI.DrawRect(new Rect(r.x+3,r.y+3,r.width-6,r.height-6),R10AuthoringPalette.WithAlpha(c,.52f));}foreach(var q in shape){var x=h.anchor.x+q.x;var y=h.anchor.y+q.y;var r=cell(x,y);var left=!shape.Any(v=>v.x+h.anchor.x==x-1&&v.y+h.anchor.y==y);var right=!shape.Any(v=>v.x+h.anchor.x==x+1&&v.y+h.anchor.y==y);var top=!shape.Any(v=>v.x+h.anchor.x==x&&v.y+h.anchor.y==y+1);var bottom=!shape.Any(v=>v.x+h.anchor.x==x&&v.y+h.anchor.y==y-1);var edge=selected?Color.white:c;if(left)EditorGUI.DrawRect(new Rect(r.x+2,r.y+2,3,r.height-4),edge);if(right)EditorGUI.DrawRect(new Rect(r.xMax-5,r.y+2,3,r.height-4),edge);if(top)EditorGUI.DrawRect(new Rect(r.x+2,r.y+2,r.width-4,3),edge);if(bottom)EditorGUI.DrawRect(new Rect(r.x+2,r.yMax-5,r.width-4,3),edge);}var anchor=cell(h.anchor.x,h.anchor.y);var dual=h.stages!=null&&h.stages.Length>1;if(dual){var next=R10AuthoringPalette.ColorFor(h.stages[1].color);EditorGUI.DrawRect(new Rect(anchor.x+9,anchor.y+9,anchor.width-18,anchor.height-18),R10AuthoringPalette.WithAlpha(next,.8f));}GUI.Label(new Rect(anchor.x+5,anchor.y+anchor.height*.42f,anchor.width-10,18),Short(h.id),Centered(10,Color.white));GUI.Label(new Rect(anchor.x+4,anchor.y+3,20,18),R10AuthoringPalette.ConstraintGlyph(h.movementConstraint),Centered(13,Color.white));var count=h.stages!=null&&h.stages.Length>0?h.stages[0].need:h.need;GUI.Label(new Rect(anchor.xMax-23,anchor.y+3,18,18),count.ToString(),Centered(10,Color.white));}
 static void DrawSprout(Rect cell,TargetDto t,bool selected){var c=R10AuthoringPalette.ColorFor(t.color);var r=new Rect(cell.center.x-cell.width*.19f,cell.center.y-cell.height*.19f,cell.width*.38f,cell.height*.38f);EditorGUI.DrawRect(new Rect(r.x-2,r.y-2,r.width+4,r.height+4),selected?Color.white:new Color(.08f,.08f,.08f,.9f));EditorGUI.DrawRect(r,c);GUI.Label(r,"?",Centered(12,Color.white));}
 static void DrawElevator(Rect cell,ElevatorDto e,bool selected){var r=new Rect(cell.x+6,cell.y+6,cell.width-12,cell.height-12);EditorGUI.DrawRect(r,selected?Color.white:new Color(.22f,.14f,.35f));EditorGUI.DrawRect(new Rect(r.x+3,r.y+3,r.width-6,r.height-6),new Color(.48f,.26f,.74f));GUI.Label(r,R10AuthoringPalette.DirectionGlyph(e.direction),Centered(22,Color.white));var n=(e.queue??Array.Empty<QueueItemDto>()).Length-e.nextIndex;GUI.Label(new Rect(r.xMax-18,r.y+2,16,16),Mathf.Max(0,n).ToString(),Centered(9,Color.white));}
 static GUIStyle Centered(int size,Color color){var s=new GUIStyle(EditorStyles.label){alignment=TextAnchor.MiddleCenter,fontSize=size,fontStyle=FontStyle.Bold,normal={textColor=color}};return s;}static string Short(string id){if(string.IsNullOrEmpty(id))return "H";return id.Length<=8?id:id.Substring(0,8);}
 static void HandleInput(R10EditorState state,R10Selection selected,R10Tool tool,Rect rect,float cell,ref string dragId,ref string dragKind){var l=state.project.level;var ev=Event.current;if(!rect.Contains(ev.mousePosition))return;var board=R10CanvasCoordinates.CanvasToBoard(rect,cell,ev.mousePosition);var allH=l.habitats??Array.Empty<HabitatDto>();var h=allH.FirstOrDefault(a=>(a.shape??Array.Empty<IntPair>()).Any(q=>a.anchor.x+q.x==board.x&&a.anchor.y+q.y==board.y));var t=(l.targets??Array.Empty<TargetDto>()).FirstOrDefault(a=>Mathf.FloorToInt(a.position.x)==board.x&&Mathf.FloorToInt(a.position.y)==board.y);var e=(l.elevators??Array.Empty<ElevatorDto>()).FirstOrDefault(a=>Mathf.FloorToInt(a.entry.x)==board.x&&Mathf.FloorToInt(a.entry.y)==board.y);if(ev.type==EventType.MouseMove){var names=new List<string>();if(h!=null)names.Add("Habitat "+h.id);if(t!=null)names.Add("Sproutling "+t.id+" ("+t.color+")");if(e!=null)names.Add("Elevator "+e.id+" ("+e.direction+")");names.Insert(0,"Cell ("+board.x+","+board.y+")");GUI.Label(new Rect(ev.mousePosition.x+12,ev.mousePosition.y+12,240,54),string.Join("\n",names),EditorStyles.helpBox);}if(ev.type==EventType.MouseDown&&ev.button==0){if(tool==R10Tool.Habitat){var id=R10Commands.AddHabitat(state,board);if(id!=null)selected.Set("Habitat",id);ev.Use();return;}if(tool==R10Tool.Sproutling){var id=R10Commands.AddTarget(state,board);if(id!=null)selected.Set("Sproutling",id);ev.Use();return;}if(tool==R10Tool.Elevator){var id=R10Commands.AddElevator(state,board);if(id!=null)selected.Set("Elevator",id);ev.Use();return;}if(tool==R10Tool.Obstacle){R10Commands.ToggleCell(state,board,true);ev.Use();return;}if(tool==R10Tool.Playable){R10Commands.ToggleCell(state,board,false);ev.Use();return;}if(h!=null){selected.Set("Habitat",h.id);dragId=h.id;dragKind=ev.shift?"DuplicateHabitat":"Habitat";}else if(t!=null){selected.Set("Sproutling",t.id);dragId=t.id;dragKind="Sproutling";}else if(e!=null){selected.Set("Elevator",e.id);dragId=e.id;dragKind="Elevator";}else selected.Clear();ev.Use();}if(ev.type==EventType.MouseUp&&ev.button==0&&!string.IsNullOrEmpty(dragId)){if(dragKind=="Habitat")R10Commands.MoveHabitat(state,dragId,board);else if(dragKind=="DuplicateHabitat"){var id=R10Commands.DuplicateHabitat(state,dragId,board);if(id!=null)selected.Set("Habitat",id);}else if(dragKind=="Sproutling")R10Commands.MoveTarget(state,dragId,board);else R10Commands.MoveElevator(state,dragId,board);dragId=dragKind=null;ev.Use();}}
}}
